                String[] parts = line.split(",");
                String query = parts[0];
                long timestamp = Long.parseLong(parts[1]);

                int hitOrMiss;
                if (topFrequentQueriesSet.contains(query)) {
                    if (cache.contains(query)) {
                        hitOrMiss = 1; // Cache hit
                    } else {
                        cache.add(query);
                        hitOrMiss = 0; // Cache miss
                    }
                } else {
                    hitOrMiss = -1; // Not in top frequent queries
                }

                return new Tuple2<>(query, hitOrMiss);
            }
        });

        // Calculate hit rate
        long totalQueries = hitMissData.count();
        long cacheHits = hitMissData.filter(new Function<Tuple2<String, Integer>, Boolean>() {
            @Override
            public Boolean call(Tuple2<String, Integer> tuple) {
                return tuple._2() == 1;
            }
        }).count();

        double hitRate = (double) cacheHits / totalQueries;

        System.out.println("Total Queries: " + totalQueries);
        System.out.println("Cache Hits: " + cacheHits);
        System.out.println("Hit Rate: " + hitRate);

        spark.stop();
    }
}
