      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={handleShowTooltip}
    >
      {children}
      {isHovered && (
        <div className={styles.tooltip}>
          {content}
          <button onClick={handleCloseTooltip}>Close</button>
        </div>
      )}
    </div>
  );
