<?php

namespace App\Http\Middleware;

use Closure;
use Firebase\Auth\TokenVerifier;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Session;

class FirebaseAuthenticateMiddleware
{
    /**
     * Handle an incoming request.
     *
     * @param  \Illuminate\Http\Request  $request
     * @param  \Closure(\Illuminate\Http\Request): (\Illuminate\Http\Response|\Illuminate\Http\RedirectResponse)  $next
     * @return \Illuminate\Http\Response|\Illuminate\Http\RedirectResponse
     */
    public function handle(Request $request, Closure $next)
    {
        $token = $request->header('Authorization'); // Assuming token is sent in Authorization header

        if ($token) {
            try {
                $verifier = new TokenVerifier(new \Firebase\Auth\FirebaseAuth(config('firebase.api_key')));
                $token = $verifier->verifyIdToken($token);
                Session::put('firebase_uid', $token->uid);
                return $next($request);
            } catch (\Exception $e) {
                // Token is invalid or expired
                return response()->json(['error' => 'Invalid Firebase token'], 401);
            }
        } else {
            // No token provided
            if (!Session::has('firebase_uid')) {
                // Generate anonymous ID and store in session
                Session::put('firebase_uid', uniqid()); // Simple anonymous ID
            }
            return $next($request);
        }
    }
}
